import { Controller } from "@hotwired/stimulus"
import { post, destroy } from "@rails/request.js"

// Turns web push on and off for this browser. The subscription the push service
// hands us is stored server-side, so notifications keep coming when Fizzy is closed.
export default class extends Controller {
  static targets = [ "switch", "details", "unsupported" ]
  static classes = [ "on" ]
  static values = { url: String, vapidPublicKey: String }

  connect() {
    this.refresh()
  }

  async toggle(event) {
    if (event.target.checked) {
      await this.subscribe()
    } else {
      await this.unsubscribe()
    }
  }

  async subscribe() {
    if (await this.#requestPermission()) {
      const subscription = await this.#pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: this.#applicationServerKey
      })

      await this.#createSubscription(subscription)
    }

    await this.refresh()
  }

  async unsubscribe() {
    const subscription = await this.#subscription

    if (subscription) {
      await subscription.unsubscribe()
      await this.#destroySubscription(subscription)
    }

    await this.refresh()
  }

  async refresh() {
    const supported = this.#supported
    const subscribed = supported && this.#permission === "granted" && !!(await this.#subscription)

    this.element.classList.toggle(this.onClass, subscribed)

    if (this.hasSwitchTarget) {
      this.switchTarget.checked = subscribed
      this.switchTarget.disabled = !supported || this.#permission === "denied"
    }

    this.unsupportedTargets.forEach(target => target.hidden = supported)
    this.detailsTargets.forEach(target => target.hidden = subscribed || !supported)
  }

  // Private

  async #createSubscription(subscription) {
    const { endpoint, keys } = subscription.toJSON()

    const response = await post(this.urlValue, {
      body: { push_subscription: { endpoint: endpoint, p256dh_key: keys.p256dh, auth_key: keys.auth } },
      responseKind: "json"
    })

    if (response.ok) {
      const { id } = await response.json
      localStorage.setItem(this.#storageKey(endpoint), id)
    }
  }

  async #destroySubscription(subscription) {
    const id = localStorage.getItem(this.#storageKey(subscription.endpoint))

    if (id) {
      localStorage.removeItem(this.#storageKey(subscription.endpoint))
      await destroy(`${this.urlValue}/${id}`, { responseKind: "json" })
    }
  }

  #storageKey(endpoint) {
    return `push_subscription:${endpoint}`
  }

  async #requestPermission() {
    return this.#permission === "granted" || (await Notification.requestPermission()) === "granted"
  }

  get #subscription() {
    return this.#supported ? this.#registration.then(registration => registration.pushManager.getSubscription()) : Promise.resolve(null)
  }

  get #pushManager() {
    return this.#registration.then(registration => registration.pushManager)
  }

  get #registration() {
    return navigator.serviceWorker.ready
  }

  get #permission() {
    return this.#supported ? Notification.permission : "denied"
  }

  get #supported() {
    return "serviceWorker" in navigator && "PushManager" in window && "Notification" in window
  }

  get #applicationServerKey() {
    const base64 = (this.vapidPublicKeyValue + "=".repeat((4 - this.vapidPublicKeyValue.length % 4) % 4)).replace(/-/g, "+").replace(/_/g, "/")
    return Uint8Array.from(atob(base64), character => character.charCodeAt(0))
  }
