// Turns web push notifications on and off for this browser. The subscription
// the push service hands us is kept server-side, so notifications keep coming
// when Fizzy is closed.
export default class extends Controller {
  static targets = [ "switch", "details", "unsupported" ]
  static classes = [ "on" ]
  static values = { url: String, vapidPublicKey: String }

  connect() {
    this.refresh()
  }

  toggle(event) {
    if (event.target.checked) {
      this.subscribe()
    } else {
      this.unsubscribe()
    }
  }

  async subscribe() {
    if (this.#supported && await this.#requestPermission()) {
      const registration = await navigator.serviceWorker.ready
      const subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: this.#applicationServerKey
      })

      await this.#createSubscription(subscription)
    }

    await this.refresh()
  }

  async unsubscribe() {
    const subscription = await this.#currentSubscription()

    if (subscription) {
      await subscription.unsubscribe()
      await this.#destroySubscription(subscription)
    }

    await this.refresh()
  }

  async refresh() {
    const supported = this.#supported
    const blocked = supported && this.#permission === "denied"
    const subscribed = supported && this.#permission === "granted" && Boolean(await this.#currentSubscription())

    this.element.classList.toggle(this.onClass, subscribed)

    if (this.hasSwitchTarget) {
      this.switchTarget.checked = subscribed
      this.switchTarget.disabled = !supported || blocked
    }

    this.unsupportedTargets.forEach(target => target.hidden = supported)
    this.detailsTargets.forEach(target => target.hidden = !blocked)
  }

  async #currentSubscription() {
    if (this.#supported) {
      const registration = await navigator.serviceWorker.ready
      return registration.pushManager.getSubscription()
    } else {
      return null
    }
  }

  async #createSubscription(subscription) {
    const { endpoint, keys } = subscription.toJSON()

    const response = await post(this.urlValue, {
      body: { push_subscription: { endpoint: endpoint, p256dh_key: keys.p256dh, auth_key: keys.auth } },
      responseKind: "json"
    })

    if (response.ok) {
      const { id } = await response.json
      localStorage.setItem(this.#storageKey(endpoint), id)
    }
  }

  async #destroySubscription(subscription) {
    const id = localStorage.getItem(this.#storageKey(subscription.endpoint))

    if (id) {
      localStorage.removeItem(this.#storageKey(subscription.endpoint))
      await destroy(`${this.urlValue}/${id}`, { responseKind: "json" })
    }
  }

  async #requestPermission() {
